import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  template: `<div>
    <h1>{{ title }}</h1>
    <p>{{ message }}</p>
    <button (click)="onClick()">Klik Saya</button>
  </div>`,
})
export class AppComponent {
  title = 'Angular Components';
  message = 'Belajar data binding di Angular';

  onClick(): void {
    this.message = 'Tombol diklik!';
  }
}
